Q: Core Dumped after copying string to 2D Array A: <pre class="lang-c prettyprint-override"><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;

#define ROWS 12
#define COLS 24

int addToList(char **list, char *string){
    int r = 0;
    for(int i = 0; i &lt; ROWS; i++){
        if(list[i] == NULL){
            puts(&quot;NULL DETECTED&quot;);
            list[i] = malloc(COLS * sizeof(char));
            if(list[i] == NULL){
                r = -1; break;
            }
            strcpy(list[i],string);
            r = 1;
            break;
        }
    }
    return r;
}

void printList(char **list){
    for(int i = 0 ; i &lt; ROWS; i++)
        fprintf(stdout,&quot;%s \n&quot;, list[i] ? list[i] : &quot;NULL&quot;);
}

int main(){

    char **list = malloc(ROWS * sizeof(char*));

    for(int i = 0; i &lt; ROWS; i++){
        list[i] = NULL;
    }

    if(list == NULL){
        fprintf(stderr,&quot;ERROR : failed to allocate list memory\n&quot;);
        return 1;
    }

    if (addToList(list,&quot;First Line&quot;) &lt; 0){
        fprintf(stderr,&quot;ERROR : failed to allocate list memory\n&quot;);
        return 1;
    }
    if (addToList(list,&quot;Second Line&quot;) &lt; 0){
        fprintf(stderr,&quot;ERROR : failed to allocate list memory\n&quot;);
        return 1;
    }

    printList(list);

    return 0;
}
</code></pre>
